# PropertySummary query - returns name, location, coordinates, reviews, space overview (features)
# Added totalCount fields to reviewSummary to get review count
PROPERTY_SUMMARY_QUERY = """query PropertySummary($context: ContextInput!, $propertyId: String!, $searchCriteria: PropertySearchCriteriaInput, $shoppingContext: ShoppingContextInput) { propertyInfo(context: $context, searchCriteria: $searchCriteria, propertyId: $propertyId, shoppingContext: $shoppingContext) { __typename summary { id name tagline location { address { addressLine city province countryCode } parentRegion { name } coordinates { latitude longitude } } spaceOverview { __typename ...propertyInfoContent } } propertyDetails { reviewSummary { overallScoreWithDescriptionA11y { value accessibilityLabel } totalCount { raw formatted } } } } }  fragment icon on Icon { id description size token theme title }  fragment httpURI on HttpURI { value relativePath }  fragment mark on Mark { __typename description token url { __typename ...httpURI } markSize: size }  fragment propertyInfoContentHeader on LodgingHeader { text subText mark { __typename ...mark } }  fragment UIGraphicFragment on UIGraphic { __typename ... on Icon { __typename ...icon } ... on Mark { __typename ...mark } }  fragment egdsGraphicText on EGDSGraphicText { text graphic { __typename ...UIGraphicFragment } }  fragment PropertyUIGraphic on UIGraphic { __typename ... on Icon { __typename ...icon } ... on Mark { __typename ...mark } }  fragment propertyInfoContentItem on PropertyInfoItem { text primary { __typename ...egdsGraphicText graphic { __typename ...PropertyUIGraphic } } icon { __typename ...icon } graphic { __typename ...PropertyUIGraphic } }  fragment propertyInfoContentItems on PropertyInfoContent { infoItems { __typename ...propertyInfoContentItem } items { __typename ...propertyInfoContentItem } }  fragment propertyInfoContent on PropertyInfoContent { __typename header { __typename ...propertyInfoContentHeader } icon { __typename ...icon } ...propertyInfoContentItems }"""

